"""Russian single-column article populated from actual saved evaluation outputs."""
from pathlib import Path
import json,re
import pandas as pd
from docx import Document
from docx.shared import Cm,Pt,RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH,WD_TAB_ALIGNMENT
from docx.enum.table import WD_TABLE_ALIGNMENT,WD_CELL_VERTICAL_ALIGNMENT
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
ROOT=Path(__file__).resolve().parents[1]
M=pd.read_csv(ROOT/'results/metrics_all_variants.csv')
PA=pd.read_csv(ROOT/'results/paired_inference.csv');EX=pd.read_csv(ROOT/'results/exploratory_inference.csv')
GRAPH=pd.read_csv(ROOT/'results/graph_statistics.csv');PAR=json.loads((ROOT/'results/selected_parameters.json').read_text())
def val(name,field='NDCG5',city='MAIN_MACRO',subset='warm'):
    return float(M[(M.model==name)&(M.city==city)&(M.split=='test')&(M.subset==subset)].iloc[0][field])
def fmt(x):return f'{float(x):.4f}'.replace('.',',')
def mr(text):
    r=OxmlElement('m:r');t=OxmlElement('m:t');t.text=text;r.append(t);return r
def sub(a,b):
    s=OxmlElement('m:sSub');e=OxmlElement('m:e');e.append(mr(a));b1=OxmlElement('m:sub');b1.append(mr(b));s.extend([e,b1]);return s
def sup(a,b):
    s=OxmlElement('m:sSup');e=OxmlElement('m:e');e.append(mr(a));b1=OxmlElement('m:sup');b1.append(mr(b));s.extend([e,b1]);return s
def frac(a,b):
    f=OxmlElement('m:f');num=OxmlElement('m:num');den=OxmlElement('m:den')
    for x in a:num.append(x)
    for x in b:den.append(x)
    f.extend([num,den]);return f
doc=Document();sec=doc.sections[0];sec.page_width=Cm(21);sec.page_height=Cm(29.7)
sec.top_margin=sec.bottom_margin=Cm(1.8);sec.left_margin=sec.right_margin=Cm(2);sec.footer_distance=Cm(.8)
for name in ['Normal','Title','Subtitle','Heading 1','Heading 2']:
    st=doc.styles[name];st.font.name='Times New Roman';st.font.color.rgb=RGBColor(0,0,0)
    f=st.element.get_or_add_rPr().rFonts
    for a in ['asciiTheme','hAnsiTheme','eastAsiaTheme','cstheme']:f.attrib.pop(qn('w:'+a),None)
    for a in ['ascii','hAnsi','eastAsia','cs']:f.set(qn('w:'+a),'Times New Roman')
for n in list(doc.styles.element.iter(qn('w:pBdr'))):n.getparent().remove(n)
normal=doc.styles['Normal'];normal.font.size=Pt(11.5);normal.paragraph_format.line_spacing=1.07;normal.paragraph_format.space_after=Pt(5);normal.paragraph_format.alignment=WD_ALIGN_PARAGRAPH.JUSTIFY;normal.paragraph_format.widow_control=True
doc.styles['Title'].font.size=Pt(18);doc.styles['Title'].font.bold=True;doc.styles['Title'].paragraph_format.alignment=WD_ALIGN_PARAGRAPH.CENTER
for name in ['Heading 1','Heading 2']:
    st=doc.styles[name];st.font.size=Pt(12);st.font.bold=name=='Heading 1';st.font.italic=name=='Heading 2';st.paragraph_format.space_before=Pt(8);st.paragraph_format.space_after=Pt(5)
def p(text,style=None):
    text=text.replace(' — ',' – ');text=re.sub(r'(?<=\d) (?=\d{3}(?:\D|$))','\u00a0',text)
    return doc.add_paragraph(text,style)
def h(t):doc.add_heading(t,1)
def page():doc.add_page_break()
def equation(parts,num):
    par=p('');par.paragraph_format.space_after=Pt(7);par.alignment=WD_ALIGN_PARAGRAPH.LEFT
    par.paragraph_format.tab_stops.add_tab_stop(Cm(8.5),WD_TAB_ALIGNMENT.CENTER);par.paragraph_format.tab_stops.add_tab_stop(Cm(17),WD_TAB_ALIGNMENT.RIGHT)
    par.add_run('\t');m=OxmlElement('m:oMath')
    for x in parts:m.append(x)
    par._p.append(m);par.add_run(f'\t({num})')
def table(cap,headers,rows,widths):
    q=p(cap);q.paragraph_format.keep_with_next=True
    for r in q.runs:r.font.size=Pt(10)
    t=doc.add_table(rows=1,cols=len(headers));t.alignment=WD_TABLE_ALIGNMENT.CENTER;t.autofit=False
    for i,w in enumerate(widths):t.columns[i].width=Cm(w)
    for i,x in enumerate(headers):t.rows[0].cells[i].text=str(x)
    for values in rows:
        for cell,x in zip(t.add_row().cells,values):cell.text=str(x)
    for ri,row in enumerate(t.rows):
        tr=row._tr.get_or_add_trPr();tr.append(OxmlElement('w:cantSplit'))
        if ri==0:tr.append(OxmlElement('w:tblHeader'))
        for ci,cell in enumerate(row.cells):
            cell.width=Cm(widths[ci]);cell.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            tc=cell._tc.get_or_add_tcPr();b=OxmlElement('w:tcBorders')
            for edge in ['top','left','bottom','right']:
                x=OxmlElement('w:'+edge);x.set(qn('w:val'),'single' if edge=='bottom' else 'nil');x.set(qn('w:sz'),'4');x.set(qn('w:color'),'888888' if ri==0 else 'D9D9D9');b.append(x)
            tc.append(b)
            mar=OxmlElement('w:tcMar')
            for edge in ['top','left','bottom','right']:
                x=OxmlElement('w:'+edge);x.set(qn('w:w'),'60');x.set(qn('w:type'),'dxa');mar.append(x)
            tc.append(mar)
            for q in cell.paragraphs:
                q.alignment=WD_ALIGN_PARAGRAPH.LEFT if ci==0 else WD_ALIGN_PARAGRAPH.CENTER;q.paragraph_format.space_after=Pt(0);q.paragraph_format.line_spacing=1
                for r in q.runs:r.font.size=Pt(10);r.bold=ri==0
    p('')
def inline(par,parts):
    m=OxmlElement('m:oMath')
    for x in parts:m.append(x)
    par._p.append(m)

title='Адаптивная рекомендация объектов культурного наследия на основе графа знаний и динамики пользовательских предпочтений'
p(title.upper(),'Title')
p('Ключевые слова: культурное наследие; граф знаний; рекомендации; динамика предпочтений; цифровая гуманитаристика.')
h('Аннотация')
abstract='Реализован метод рекомендации следующего культурного места, объединяющий графовую диффузию, поведенческое сходство объектов и адаптивное сочетание двух профилей пользователя. Из Flickr и Wikidata сформирована выборка 78 достопримечательностей Будапешта, Вены и Эдинбурга с 120 культурными связями. Основное временное тестирование включает 272 предсказания для 47 пользователей; Эдинбург использован для проверки переноса гиперпараметров. На валидации оптимальная свободная настройка выбрала нулевой вклад графовой оценки и только текущий профиль. Её NDCG@5 составила 0,2692, адаптивного варианта — 0,2615. При обязательном ненулевом вкладе графа получено 0,2572 против 0,2263 для варианта с категориями, однако преимущество над теми же сведениями без диффузии статистически не подтверждено. Метод переходов Маркова достиг 0,4161. Проверены доверительные интервалы по пользователям, перестановки рёбер, пропуски связей и сценарий новых мест. Исходные гипотезы об улучшении рекомендаций не получили устойчивого подтверждения на изученной выборке. Представлены воспроизводимая реализация и ограничения применимости.'
p(abstract)
h('1 Введение')
p('Культурный интерес не всегда совпадает с категорией места. Музей, дворец и исторический дом могут быть связаны архитектором, стилем или личностью, хотя в туристическом каталоге они находятся в разных разделах. Персонализация культурного туризма поэтому требует описывать содержание достопримечательностей и проверять, помогает ли оно выбирать следующее место. Сочетание предпочтений и типов культурных посетителей рассматривается, например, в [1].')
p('Наблюдаемое поведение меняется и в пределах поездки. Более ранняя история может отражать устойчивые интересы, а начало текущей последовательности — локальную тему. При короткой истории такая интерпретация ненадёжна: выбор также зависит от близости мест, доступности и особенностей регистрации посещений. Работа проверяет, дают ли культурные связи дополнительную пользу при адаптации веса двух профилей.')
p('Графовые туристические рекомендации исследуются в [2], культурное обогащение графа — в CuPe-KG [3], совместное использование графовых отношений и предпочтений — в [4]. Следовательно, сам факт добавления графа недостаточен как научный вклад. Здесь вклад состоит в воспроизводимом раздельном сравнении культурных связей и адаптации на согласованных объектах, с сохранением отрицательных результатов. Выбор сильных простых сравнений соответствует вопросам воспроизводимости, поставленным в [5].')
p('Рассматривается рекомендация следующей отличающейся культурной достопримечательности внутри города. H1 предполагает улучшение при использовании культурных связей относительно варианта без них. H2 предполагает пользу адаптивного веса относительно постоянного на том же графе при изменении наблюдаемого поведения. Проверяется качество ранжирования; выводы о реальном интересе или удовлетворённости посетителя по фотографиям не делаются.')

page();h('2 Данные и предметная проверка')
p('Поведенческая основа — авторский архив Flickr User–POI Visits [6], содержащий 153 208 строк фотографий восьми городов. Посещения восстановлены как непрерывные серии снимков одного места внутри исходной последовательности; возврат после другого объекта сохранён. После отделения 53 строк с непригодными временными метками осталось 153 155 фотографий и 33 778 посещений. В основном анализе используются даты с 2000 года, а границы 1990 и 2004 годов проверены отдельно.')
p('Культурные сведения получены из снимка Wikidata [7] от 26 октября 2026 года с использованием модели исторической застройки [8]. Проверены названия, официальные перенаправления статей и координаты. Одинаковые записи Osaka Castle и Belvedere объединены с сохранением идентификаторов. National Museum of Scotland и Royal Museum трактуются как один комплекс на Chambers Street, что согласуется с описанием музея [9]. Организация, здание и комплекс не считаются взаимозаменяемыми сущностями без отдельного решения.')
p('Для трёх городов зафиксирована пообъектная таблица включения. В неё входят музеи и библиотеки, памятники, дворцы и замки, религиозные объекты, исторические общественные здания и инфраструктура, учреждения исполнительских искусств и подтверждённые исторические сады. Общие природные территории и неоднозначные идентичности исключены. Это исследовательская разметка культурных достопримечательностей; независимая экспертная разметка и проверка полноты государственного реестра не проводились.')
p('Для графа оставлены отношения с архитектором (P84), архитектурным стилем (P149) и сущностью, в честь которой назван объект (P138). Каждая связь сохраняет исходный идентификатор утверждения, редакцию, квалификаторы и сведения о ссылках. Из 120 связей 65 содержат хотя бы одну ссылку в Wikidata. Поздние события, современные охранные статусы и век основания не использовались как признаки ранжирования.')
table('Таблица 1 Культурная выборка и графы после аудита', ['Город','Места','Культурные\nрёбра','Все рёбра\nграфа','Компоненты','Места с\nкульт. связями'],[['Будапешт',30,59,89,2,'23 из 30'],['Вена',25,42,67,3,'18 из 25'],['Эдинбург',23,19,42,8,'11 из 23']],[3.2,1.7,2.9,2.9,2.5,3.8])
p('Все графы дополнены одинаковым типом ребра к функциональной категории места. Места без культурных атрибутов сохраняются среди кандидатов. Большинство культурных сущностей встречается только у одной достопримечательности: общих для нескольких объектов сущностей 10 из 42 в Будапеште, 3 из 37 в Вене и 1 из 18 в Эдинбурге. Это ограничивает возможности распространения интереса между местами.')
p('Снимок 2026 года применяется как ретроспективное описание более старых посещений. Эксперимент не доказывает, что эти сведения были доступны системе в соответствующий исторический момент. Для практического воспроизведения старой онлайн-системы потребовались бы исторические снимки знаний.')

page();h('3 Реализованный метод')
p('Пусть строки матрицы F соответствуют местам, а столбцы — типизированным культурным сущностям и функциональным категориям. Вес связи внутри каждого типа делится на количество значений этого типа у места. Так объект с тремя архитекторами не получает втрое больший общий вес этого отношения. Из F строится взвешенный неориентированный двудольный граф, а из нормированных по строкам весов — переходная матрица P.')
p('Близость мест вычисляется случайным блужданием с возвратом, используемым для оценки связности графовых узлов [10]. Для всех начальных узлов одновременно рассчитывается матрица')
equation([sub('R','λ'),mr(' = λ '),sup('[I − (1 − λ)P]','−1')],1)
p('В (1) λ — вероятность возврата. Из блока «место — место» удаляется диагональ, затем строки нормируются. Полученная матрица K переносит вес посещённого объекта на другие места. При отсутствии переходов используется популярность по обучающим данным. Проверка итерационным блужданием на контрольном графе даёт тот же результат, что и решение системы (1).')
p('Поведенческая матрица C — косинусное сходство бинарных обучающих взаимодействий «пользователь – место», умноженное на g/(g + 5), где g — число общих пользователей. Диагональ удаляется, строки нормируются. Матрица B = (1 − η)C + ηK объединяет поведение и граф. Нулевой вес η разрешён.')
q=p('Более ранний профиль ');inline(q,[sub('h','L')]);q.add_run(' содержит нормированные частоты посещений в завершённых предыдущих последовательностях; текущий ');inline(q,[sub('h','S')]);q.add_run(' — частоты в наблюдаемом префиксе. Вектор оценок равен')
equation([sub('s','t'),mr(' = (1 − '),sub('α','t'),mr(') '),sub('h','L'),mr('B + '),sub('α','t'),mr(' '),sub('h','S'),mr('B')],2)
p('Без более ранней истории применяется только текущий профиль. Для адаптивного варианта вес определяется формулой')
equation([sub('α','t'),mr(' = '),sub('α','min'),mr(' + ('),sub('α','max'),mr(' − '),sub('α','min'),mr(') '),sub('d','t'),mr(' '),frac([sub('n','t')],[sub('n','t'),mr(' + c')])],3)
q=p('В (3) ');inline(q,[sub('n','t')]);q.add_run(' — число посещений в префиксе, c > 0 — параметр доверия к короткой истории. Различие ');inline(q,[sub('d','t')]);q.add_run(' равно половине суммы модулей разностей нормированных культурных распределений профилей. Если культурных атрибутов одного профиля нет, различие принимается равным нулю. Границы веса лежат в [0; 1], верхняя строго больше нижней.')
p('Сначала на валидации выбираются λ, η и постоянная α; затем на той же матрице B подбираются параметры (3). Это отделяет адаптацию профиля от перенастройки графа. Реализация на NumPy и SciPy сохраняет матрицы и поддерживает отдельный вызов рекомендации.')

page();h('4 Протокол эксперимента')
p('Внутри каждого города целые исходные последовательности упорядочены по времени завершения. Первые 60% образуют обучение, следующие 20% — валидацию, оставшиеся 20% — тест. Совпадающие граничные времена относятся к более ранней части. Пользовательские профили содержат только наблюдения, доступные перед предсказанием; предыдущая последовательность должна завершиться раньше начала текущей. Сами обученные матрицы после валидации не обновляются.')
p('Основной сценарий требует не менее трёх посещений в более ранних последовательностях и не менее двух в текущем префиксе. Тест Будапешта включает 158 предсказаний для 31 пользователя, Вены — 114 для 21. Пять идентификаторов встречаются в обоих городах, поэтому суммарно это 272 предсказания и 47 уникальных пользователей. На валидации — 263 предсказания для 54 уникальных пользователей. Эдинбург не участвовал в подборе параметров: его 225 тестовых предсказаний для 41 пользователя проверяют перенос настроек при локально обученной поведенческой матрице.')
p('Кандидатами служат все включённые места города, кроме последнего посещённого. Возвраты к более ранним местам разрешены. Негативные примеры не сэмплируются. После удаления некультурных мест соседние одинаковые культурные идентификаторы свёрнуты: предсказывается следующий отличающийся культурный объект, а не обязательно следующий физический пункт маршрута.')
p('Сравниваются популярность, переходы Маркова первого порядка, ItemKNN, линейная модель EASE [11], географическая близость, граф с одними категориями, граф с культурными связями и информационно сопоставимый вариант с косинусным сходством тех же признаков F без диффузии. Последний отделяет эффект структуры от добавления сведений. Для Маркова и EASE используются только обучающие наблюдения; редкие и неизвестные переходы разрешаются одинаковым обучающим правилом обработки равных оценок.')
p('Для λ проверяются 0,15; 0,3; 0,5; 0,7, для η — 0; 0,25; 0,5; 0,75; 1, для постоянной α — значения от 0 до 1 с шагом 0,1. Допустимые границы адаптивного веса и параметр c выбираются на валидации из 24 комбинаций. Целевой критерий — средняя NDCG@5, сначала по событиям каждого пользователя, затем по пользователям города и поровну по двум основным городам. Все сетки и результаты выбора сохранены.')
p('Основная H1 сопоставляет лучшие валидационные варианты с культурными связями и без них. Для H2 отдельно выделяется большое изменение функциональных категорий между двумя профилями: расстояние полной вариации не ниже 75-го процентиля обучающих контекстов, то есть 0,75. Критерий использует наблюдаемый префикс, не будущий ответ и не успешность модели. В этой части основного теста 59 контекстов для 26 пользователей.')
p('Приводятся NDCG@5, доля попаданий HR@5 и MRR; дополнительные значения для K = 10 сохранены. Парные доверительные интервалы рассчитаны кластерным бутстрэпом по 10 000 выборкам пользователей. Общий идентификатор Flickr получает одинаковый вес в обоих городах. Для p-значений используется перестановка знаков пользовательских разностей; две основные проверки корректируются методом Холма. Локальный протокол зафиксирован до расчёта тестовых оценок, без заявления о внешней пререгистрации.')

page();h('5 Качество рекомендаций')
p('На валидации лучшая свободная настройка культурного гибрида выбрала η = 0 и α = 1. При таком выборе графовая оценка не участвует в ранжировании, а используется только текущий поведенческий профиль. Совпадение результатов с ItemKNN и категориальным вариантом в таблице 2 является следствием этой настройки, а не тремя независимыми подтверждениями одинакового качества.')
rows=[]
labels=[('Popularity','Популярность'),('Markov','Переходы Маркова'),('ItemKNN','ItemKNN'),('EASE','EASE'),('GeoFixed','Географическая модель'),('CulturalFixed','Культурный гибрид, свободная η'),('CulturalAdaptive','Тот же гибрид с адаптацией'),('CulturalFixedForced','Культурный граф, η ≥ 0,25*')]
for code,name in labels:rows.append([name,fmt(val(code)),fmt(val(code,'HR5')),fmt(val(code,'MRR')),fmt(val(code,city='Edin'))])
table('Таблица 2 Тестовое качество с доступными двумя профилями', ['Метод','NDCG@5\nосн. города','HR@5\nосн. города','MRR\nосн. города','NDCG@5\nЭдинбург'],rows,[6.3,2.8,2.6,2.5,2.8])
p('* Вариант с обязательным ненулевым вкладом графа — дополнительный разведочный анализ, введённый после обнаружения η = 0. Он не заменяет первоначальные проверки.')
p(f'В основных городах метод переходов Маркова достиг NDCG@5 = {fmt(val("Markov"))}. Это выше {fmt(val("CulturalFixed"))} у свободного гибрида и {fmt(val("CulturalAdaptive"))} у адаптивного. На Эдинбурге порядок основных результатов также не поддерживает преимущество культурного гибрида. У адаптации относительно постоянного веса на всех основных контекстах разность NDCG@5 равна −0,0077, 95%-й интервал [−0,0336; 0,0154].')
p('Для H1 разность свободно настроенных культурного и категориального вариантов равна нулю: оба фактически выбрали поведенческую часть. Это не оценка отсутствия любого полезного культурного сигнала. Для H2 в группе большого изменения категорий получена разность +0,0018, интервал [0,0000; 0,0062], двустороннее p = 1,000. Ненулевые различия сосредоточены у малого числа пользователей; после поправки значимого преимущества нет. Обе исходные гипотезы не получили устойчивого подтверждения.')
p('Чтобы исследовать сам графовый компонент при η > 0, повторно использована сохранённая валидационная сетка с ограничением η ≥ 0,25. Выбраны η = 0,25, λ = 0,15 и α = 1. Культурный граф получил 0,2572 против 0,2263 у лучшего варианта с одними категориями и 0,2327 у плоских культурных признаков. Для последнего сравнения парная разность +0,0245 имеет интервал [−0,0018; 0,0529]. Убедительного преимущества графовой структуры нет.')
p('При одинаковых положительной η и остальных параметрах удаление культурных рёбер уменьшает NDCG@5 на 0,0334; сырой уровень p = 0,0423 становится 0,2115 после поправки на шесть разведочных сравнений. Это условный эффект в выбранной архитектуре, требующий независимой проверки. Вариант с графом остаётся слабее модели переходов. Добавление адаптации к положительному графовому компоненту изменяет общий результат лишь на +0,0006, с интервалом [−0,0270; 0,0306].')

page();h('6 Устойчивость и границы интерпретации')
p('Культурный граф с обязательной η = 0,25 дополнительно проверен при 20 перестановках культурных рёбер, сохраняющих степени мест и сущностей внутри типа отношения. Средняя NDCG@5 после перестановок равна 0,2312, диапазон [0,2144; 0,2487], против 0,2572 на исходном графе. Исходные связи дают более высокую оценку, чем эти случайные версии. Это дополнительный результат той же тестовой выборки; он не подтверждает исходную H1 относительно лучшего поведенческого метода.')
p('При удалении 10%, 25% и 50% культурных рёбер, по десять запусков для каждого уровня, средняя NDCG@5 составляет 0,2511; 0,2413 и 0,2236 соответственно (рис. 1). Удаление связей с архитекторами даёт 0,2253, стилей — 0,2502, именования — 0,2560. Такие удаления измеряют чувствительность уже выбранной конфигурации: параметры при повреждении графа не переобучались. У свободного варианта с η = 0 эти проверки закономерно не меняют результат.')
fig=p('');fig.alignment=WD_ALIGN_PARAGRAPH.CENTER;fig.add_run().add_picture(str(ROOT/'figures/edge_dropout.png'),width=Cm(14.8))
cap=p('Рисунок 1 Чувствительность варианта с положительным графовым весом к пропускам связей. Показаны средние и диапазоны десяти запусков; это не доверительные интервалы по пользователям.')
for r in cap.runs:r.font.size=Pt(10)
p('В основной выборке 129 из 272 целей уже встречались в наблюдаемой истории. В дополнительном сценарии только новых мест такие контексты исключены, а все ранее встречавшиеся места удалены из кандидатов у каждого метода. Для 143 предсказаний и 38 пользователей NDCG@5 составила 0,5401 у Маркова, 0,4454 у свободного гибрида и 0,4008 у варианта с обязательным графом. Адаптация свободного гибрида дала 0,4472; парная разность +0,0018 имеет интервал [−0,0397; 0,0440]. Основной вывод сохраняется, хотя абсолютные метрики этого режима нельзя напрямую сравнивать с таблицей 2 из-за другого состава целей и кандидатов.')
p('Медианный перерыв до предыдущей последовательности составляет 0,74 суток в Будапеште и 0,86 суток в Вене. Поэтому более ранний профиль во многих случаях характеризует соседние части одной поездки. Название «долгосрочный» здесь условно и не доказывает устойчивость предпочтений на протяжении месяцев. На Эдинбурге 75,6% целей являются возвратами, а общих культурных сущностей особенно мало. Это существенно ограничивает обобщение.')

page();h('7 Значение результатов и ограничения')
p('Для изученного корпуса важнее оказались наблюдаемые переходы между местами и текущая история. Такая закономерность согласуется с пространственной близостью целей: доля следующих культурных мест в пределах километра от последнего составляет 67,1% в Будапеште и 78,1% в Вене. Это описательные показатели; они не устанавливают причин выбора и не исключают роли культурных мотивов.')
p('Предлагаемая адаптация основана на предположении, что расхождение профилей должно увеличивать вес текущих интересов. Само это предположение недостаточно: небольшое число наблюдений и неполнота атрибутов мешают оценить, какой профиль окажется полезным. Валидация предпочла постоянный вес, полностью ориентированный на текущий профиль. Формула доверия ограничивает адаптацию даже тогда, когда более ранние действия не помогают, что объясняет необходимость проверки постоянного веса как полноценного конкурента.')
p('Граф содержит сведения о связях предметной области, но это не гарантирует улучшения ранжирования. Большая часть архитекторов и стилей связывает лишь одно место с уникальной сущностью. Статические описания получены позднее посещений, сведения Wikidata неодинаково полны и не всегда снабжены внешними ссылками. Независимой проверки каждой исторической атрибуции специалистом не было. Прикладное использование требует дополнительной верификации и актуальных данных о доступности мест.')
p('Временное тестирование охватывает несколько сотен контекстов, но основная статистическая единица — только 47 пользователей. Повторяющиеся действия одного человека зависимы. Поэтому применены пользовательские кластеры, а не интервалы, предполагающие независимость всех переходов. Разведочные проверки ненулевого графа, повреждений и новых мест проведены после просмотра основных результатов и обозначены отдельно. Они не образуют независимых репликаций.')
p('Код сохраняет таблицу предметных решений, графы, матрицы моделей, валидационные сетки, предсказания и протокол. Проверены отсутствие будущих действий в профиле, разделение целых последовательностей, формулы метрик, решение диффузии, оптимальность EASE, обучающие счётчики переходов и совпадение отдельного вызова рекомендации с экспериментом. Пятнадцать автоматических проверок пройдены. Примеры рекомендаций выбраны как первые подходящие тестовые контексты, а не по успешности.')
h('8 Заключение')
p('Метод культурной графовой рекомендации с двумя профилями реализован и экспериментально оценён. В свободной настройке валидация выбрала нулевой вклад графовой оценки и только текущий поведенческий профиль. Адаптация не дала устойчивого преимущества; обе исходные гипотезы на изученных данных не подтверждены. Лучший результат среди рассмотренных методов показали переходы Маркова.')
p('При обязательном использовании графа культурные связи дают условный положительный эффект относительно категорий и случайно переставленных связей. Однако преимущества над информационно сопоставимым плоским описанием и сильным поведенческим сравнением не установлено. Результат ограничивает область применимости предложенного механизма: культурная связность и наличие более ранней истории сами по себе не достаточны для улучшения следующего выбора. Дальнейшая проверка требует более длительных пользовательских историй и независимого корпуса культурных посещений.')

